fn vec_min_i8(arr: &Vec<i8>) -> i8 {
    // Since arr is non-empty, unwrap is safe here.
    *arr.iter().min().unwrap()
}

fn vec_max_i8(arr: &Vec<i8>) -> i8 {
    // Since arr is non-empty, unwrap is safe here.
    *arr.iter().max().unwrap()
}

